/*
 * THE GAME'S PHOTOGRAPHS — the club's table, and what is lying on it.
 *
 * Every one is the same overhead flat-lay on dark wood as the homepage hero,
 * generated by scripts/generate-game-art.mjs (full-size masters stay outside
 * the repo in ../game-art-wip/; public/ gets WebP sized for where it shows).
 * None of them contains a word, a letter or a number, so a picture can be
 * mirrored for the right-to-left page and cropped to any strip without cutting
 * anything that has to be read.
 *
 * LITERAL PATHS, on purpose. scripts/check-image-refs.mjs finds a shipped image
 * by looking for its file name in the source; a path assembled from a template
 * (`./images/game/${kind}.webp`) would leave every one of these reported as
 * unreferenced. A book's own picture is declared the same way, in its
 * `game.js` (`gameArt`), beside the questions it illustrates.
 *
 * Imported by Home (for the game's card), so this file must stay what it is:
 * a handful of strings. Nothing here may import the game.
 */
export const GAME_ART = {
  // The game's door. `cover` is a wide strip with the pieces on the RIGHT and
  // bare wood on the left for the words (mirrored in Arabic — see `.game-cover`);
  // `coverTall` is the phone's poster, pieces above and bare wood below.
  cover: './images/game/cover.webp',
  coverTall: './images/game/cover-tall.webp',
  // The stage's ground: an empty table top, shown under a dark veil.
  table: './images/game/table.webp',
  // The band across each kind of card that is not a book's question.
  tf: './images/game/tf.webp',
  luck: './images/game/luck.webp',
  dare: './images/game/dare.webp',
  // The last square, and the result.
  win: './images/game/win.webp',
}
